1	import { createMetadata } from "@/lib/seo/metadata";
2	import { JsonLd, breadcrumbSchema } from "@/lib/seo/jsonld";
3	import { SITE_CONFIG } from "@/lib/constants/site";
4	import { BLOG_POSTS } from "@/lib/constants/blog";
5	import { GradientPageBg } from "@/components/shared/page-bg";
6	import { BlogHero } from "@/components/blog/blog-hero";
7	import { BlogGrid } from "@/components/blog/blog-grid";
8	import { BlogBottomCta } from "@/components/blog/blog-bottom-cta";
9	import { BetaCta } from "@/components/shared/beta-cta";
10	
11	export const metadata = createMetadata({
12	  title: "Agency Growth Blog | White Label Web Dev Insights | Boldteq",
13	  description:
14	    "Practical insights on white-label outsourcing, agency growth, web delivery systems, and conversion-focused execution — written for agencies that want to scale.",
15	  path: "/blog",
16	});
17	
18	const breadcrumbs = breadcrumbSchema([{ name: "Blog", path: "/blog" }]);
19	
20	const blogSchema = {
21	  "@context": "https://schema.org",
22	  "@type": "Blog",
23	  name: `${SITE_CONFIG.name} Blog`,
24	  url: `${SITE_CONFIG.url}/blog`,
25	  description:
26	    "Practical insights on white-label outsourcing, agency growth, and execution systems for scaling agencies.",
27	  publisher: {
28	    "@type": "Organization",
29	    name: SITE_CONFIG.name,
30	    url: SITE_CONFIG.url,
31	  },
32	  blogPost: BLOG_POSTS.map((post) => ({
33	    "@type": "BlogPosting",
34	    headline: post.title,
35	    description: post.shortDescription,
36	    image: post.image,
37	    url: `${SITE_CONFIG.url}/blog/${post.slug}`,
38	  })),
39	};
40	
41	export default function BlogPage() {
42	  return (
43	    <>
44	      <JsonLd data={breadcrumbs} id="schema-breadcrumbs" />
45	      <JsonLd data={blogSchema} id="schema-blog" />
46	      <GradientPageBg />
47	      <BlogHero />
48	      <BlogGrid />
49	      <BlogBottomCta />
50	      <BetaCta />
51	    </>
52	  );
53	}
