1	import { notFound } from "next/navigation";
2	import { BLOG_POSTS } from "@/lib/constants/blog";
3	import { createMetadata } from "@/lib/seo/metadata";
4	import { JsonLd, breadcrumbSchema } from "@/lib/seo/jsonld";
5	import { SITE_CONFIG } from "@/lib/constants/site";
6	import { BlogDetailView } from "@/components/blog/detail/blog-detail-view";
7	import { BetaCta } from "@/components/shared/beta-cta";
8	import { GradientPageBg } from "@/components/shared/page-bg";
9	
10	export function generateStaticParams() {
11	  return BLOG_POSTS.map((post) => ({ slug: post.slug }));
12	}
13	
14	export async function generateMetadata({
15	  params,
16	}: {
17	  params: Promise<{ slug: string }>;
18	}) {
19	  const { slug } = await params;
20	  const post = BLOG_POSTS.find((p) => p.slug === slug);
21	  if (!post) return {};
22	  return createMetadata({
23	    title: `${post.title} | Boldteq Blog`,
24	    description: post.shortDescription,
25	    path: `/blog/${post.slug}`,
26	    ogImage: post.image,
27	    type: "article",
28	    authors: [SITE_CONFIG.name],
29	    publishedTime: post.publishedAt,
30	    modifiedTime: post.updatedAt ?? post.publishedAt,
31	  });
32	}
33	
34	export default async function BlogDetailPage({
35	  params,
36	}: {
37	  params: Promise<{ slug: string }>;
38	}) {
39	  const { slug } = await params;
40	  const post = BLOG_POSTS.find((p) => p.slug === slug);
41	  if (!post) notFound();
42	
43	  // Related posts: same category, excluding current
44	  const related = BLOG_POSTS.filter(
45	    (p) => p.slug !== post.slug && p.category === post.category,
46	  ).slice(0, 3);
47	
48	  // If fewer than 3 related, fill from other posts
49	  const relatedPosts =
50	    related.length >= 2
51	      ? related
52	      : [
53	          ...related,
54	          ...BLOG_POSTS.filter(
55	            (p) =>
56	              p.slug !== post.slug &&
57	              !related.find((r) => r.slug === p.slug),
58	          ).slice(0, 3 - related.length),
59	        ];
60	
61	  const breadcrumbs = breadcrumbSchema([
62	    { name: "Blog", path: "/blog" },
63	    { name: post.title, path: `/blog/${post.slug}` },
64	  ]);
65	
66	  const articleSchema = {
67	    "@context": "https://schema.org",
68	    "@type": "BlogPosting",
69	    headline: post.title,
70	    description: post.shortDescription,
71	    image: post.image,
72	    datePublished: post.publishedAt,
73	    dateModified: post.updatedAt ?? post.publishedAt,
74	    url: `${SITE_CONFIG.url}/blog/${post.slug}`,
75	    mainEntityOfPage: {
76	      "@type": "WebPage",
77	      "@id": `${SITE_CONFIG.url}/blog/${post.slug}`,
78	    },
79	    author: {
80	      "@type": "Organization",
81	      name: SITE_CONFIG.name,
82	      url: SITE_CONFIG.url,
83	    },
84	    publisher: {
85	      "@type": "Organization",
86	      name: SITE_CONFIG.name,
87	      logo: {
88	        "@type": "ImageObject",
89	        url: "https://cdn.prod.website-files.com/68ee3857579ec95674c7dd80/6937cbaf47872f6a8eb16f1c_Group%2046895.svg",
90	      },
91	    },
92	    articleSection: post.category,
93	    inLanguage: "en-US",
94	  };
95	
96	  return (
97	    <>
98	      <JsonLd data={breadcrumbs} id="schema-breadcrumbs" />
99	      <JsonLd data={articleSchema} id="schema-article" />
100	      <GradientPageBg />
101	      <BlogDetailView post={post} relatedPosts={relatedPosts} />
102	      <BetaCta />
103	    </>
104	  );
105	}
