1	"use client";
2	
3	import { useState, useMemo } from "react";
4	import Image from "next/image";
5	import { BLOG_POSTS, BLOG_CATEGORIES } from "@/lib/constants/blog";
6	import { BlogCard } from "./blog-card";
7	import styles from "./blog-grid.module.css";
8	
9	const CATEGORY_LABELS: Record<string, string> = {
10	  all: "All",
11	  cro: "CRO",
12	  shopify: "Shopify",
13	  "ui-ux-design": "UI/UX Design",
14	  "web-development": "Web Development",
15	  "white-label-outsourcing": "White-Label & Outsourcing",
16	  wordpress: "WordPress",
17	};
18	
19	export function BlogGrid() {
20	  const [activeCategory, setActiveCategory] = useState<string>("all");
21	  const [searchQuery, setSearchQuery] = useState<string>("");
22	
23	  const filtered = useMemo(() => {
24	    return BLOG_POSTS.filter((post) => {
25	      const matchesCategory =
26	        activeCategory === "all" || post.category === activeCategory;
27	      const normalizedQuery = searchQuery.trim().toLowerCase();
28	      const matchesSearch =
29	        normalizedQuery === "" ||
30	        post.title.toLowerCase().includes(normalizedQuery) ||
31	        post.shortDescription.toLowerCase().includes(normalizedQuery) ||
32	        post.category.toLowerCase().includes(normalizedQuery);
33	      return matchesCategory && matchesSearch;
34	    });
35	  }, [activeCategory, searchQuery]);
36	
37	  const topPosts = useMemo(() => BLOG_POSTS.slice(0, 4), []);
38	
39	  const handleClearCategory = () => {
40	    setActiveCategory("all");
41	  };
42	
43	  return (
44	    <section className={styles.section}>
45	      <div className={styles.tabsContainer}>
46	        <div className={styles.filtOut}>
47	          <div className={styles.filterGrid}>
48	            {/* ── LEFT SIDEBAR ── */}
49	            <div className={styles.filterColumn}>
50	              {/* Search */}
51	              <div className={styles.searchBlock}>
52	                <input
53	                  type="search"
54	                  className={styles.searchField}
55	                  placeholder="Search here..."
56	                  value={searchQuery}
57	                  onChange={(e) => setSearchQuery(e.target.value)}
58	                  aria-label="Search blog articles"
59	                />
60	              </div>
61	
62	              {/* Categories */}
63	              <div className={styles.filterBlock}>
64	                <div className={styles.filterBlockHeader}>
65	                  <button
66	                    type="button"
67	                    className={styles.filterReset}
68	                    onClick={handleClearCategory}
69	                    aria-label="Clear category filter"
70	                  >
71	                    Clear
72	                  </button>
73	                  <h3 className={styles.filterBarTitle}>Categories</h3>
74	                </div>
75	                <div className={styles.filterOptions}>
76	                  <ul className={styles.categoryList} role="list">
77	                    {BLOG_CATEGORIES.map((cat) => {
78	                      const isActive = activeCategory === cat.slug;
79	                      return (
80	                        <li key={cat.slug} className={styles.categoryItem}>
81	                          <input
82	                            type="checkbox"
83	                            id={`cat-${cat.slug}`}
84	                            className={styles.categoryCheckbox}
85	                            checked={isActive}
86	                            onChange={() =>
87	                              setActiveCategory(isActive ? "all" : cat.slug)
88	                            }
89	                            aria-label={`Filter by ${cat.name}`}
90	                          />
91	                          <label
92	                            htmlFor={`cat-${cat.slug}`}
93	                            className={`${styles.categoryLabel} ${isActive ? styles.categoryLabelActive : ""}`}
94	                          >
95	                            {cat.name}
96	                          </label>
97	                        </li>
98	                      );
99	                    })}
100	                  </ul>
101	                </div>
102	              </div>
103	
104	              {/* Top Posts */}
105	              <div className={styles.filterBlock}>
106	                <div className={styles.filterBlockHeader}>
107	                  <span />
108	                  <h3 className={styles.filterBarTitle}>Top Posts</h3>
109	                </div>
110	                <div className={styles.filterOptions}>
111	                  <ul className={styles.topPostsList} role="list">
112	                    {topPosts.map((post, index) => (
113	                      <li key={post.slug} className={styles.topPostItem}>
114	                        <span
115	                          className={styles.topPostNumber}
116	                          aria-hidden="true"
117	                        >
118	                          {String(index + 1).padStart(2, "0")}
119	                        </span>
120	                        <div className={styles.topPostInner}>
121	                          <a
122	                            href={`/blog/${post.slug}`}
123	                            className={styles.topPostTitle}
124	                          >
125	                            {post.title}
126	                          </a>
127	                          <p className={styles.topPostCat}>
128	                            {CATEGORY_LABELS[post.category] ?? post.category}
129	                          </p>
130	                        </div>
131	                      </li>
132	                    ))}
133	                  </ul>
134	                </div>
135	              </div>
136	
137	              {/* Follow Us */}
138	              <div className={styles.filterBlock}>
139	                <div className={styles.filterBlockHeader}>
140	                  <span />
141	                  <h3 className={styles.filterBarTitle}>Follow Us</h3>
142	                </div>
143	                <div className={styles.filterOptions}>
144	                  <div className={styles.socialRow}>
145	                    <a
146	                      href="https://www.linkedin.com/company/boldteq"
147	                      target="_blank"
148	                      rel="noopener noreferrer"
149	                      className={styles.socialLink}
150	                      aria-label="Boldteq on LinkedIn"
151	                    >
152	                      <Image
153	                        src="/images/webflow/ri_linkedin-fill.svg"
154	                        alt="LinkedIn"
155	                        width={24}
156	                        height={24}
157	                      />
158	                    </a>
159	                    <a
160	                      href="https://www.instagram.com/boldteq/"
161	                      target="_blank"
162	                      rel="noopener noreferrer"
163	                      className={styles.socialLink}
164	                      aria-label="Boldteq on Instagram"
165	                    >
166	                      <Image
167	                        src="/images/webflow/mdi_instagram.svg"
168	                        alt="Instagram"
169	                        width={24}
170	                        height={24}
171	                      />
172	                    </a>
173	                    <a
174	                      href="https://www.facebook.com/people/Boldteq-Global-Pvt-Ltd/100070645008632/"
175	                      target="_blank"
176	                      rel="noopener noreferrer"
177	                      className={styles.socialLink}
178	                      aria-label="Boldteq on Facebook"
179	                    >
180	                      <Image
181	                        src="/images/webflow/basil_facebook-solid.svg"
182	                        alt="Facebook"
183	                        width={24}
184	                        height={24}
185	                      />
186	                    </a>
187	                  </div>
188	                </div>
189	              </div>
190	            </div>
191	
192	            {/* ── RIGHT CONTENT ── */}
193	            <div className={styles.filterContent}>
194	              {filtered.length === 0 ? (
195	                <div className={styles.emptyState}>
196	                  <Image
197	                    src="/images/webflow/Group.svg"
198	                    alt=""
199	                    width={80}
200	                    height={80}
201	                    className={styles.emptyIcon}
202	                    aria-hidden="true"
203	                  />
204	                  <p className={styles.emptyText}>No results found.</p>
205	                </div>
206	              ) : (
207	                <ul className={styles.grid} role="list">
208	                  {filtered.map((post) => (
209	                    <li key={post.slug}>
210	                      <BlogCard post={post} />
211	                    </li>
212	                  ))}
213	                </ul>
214	              )}
215	            </div>
216	          </div>
217	        </div>
218	      </div>
219	    </section>
220	  );
221	}
